  const red = (x, d = 4) => (x === null || !Number.isFinite(x) ? null : Math.round(x * 10 ** d) / 10 ** d);

  /** T de Student al 95 % para dos colas, aproximada. Suficiente para gl >= 1 con error < 0,01. */
