    for (let i = 0; i < n; i++) { const dx = xs[i] - mx, dy = ys[i] - my; sxx += dx * dx; sxy += dx * dy; syy += dy * dy; }
    if (sxx === 0) return { n, pendiente: null, intercepto: null, r2: null, ic95: null };
    const pendiente = sxy / sxx;
    const intercepto = my - pendiente * mx;
