    const ma = a.reduce((s, x) => s + x, 0) / na;
    const mb = b.reduce((s, x) => s + x, 0) / nb;
    const va = a.reduce((s, x) => s + (x - ma) ** 2, 0) / (na - 1);
    const vb = b.reduce((s, x) => s + (x - mb) ** 2, 0) / (nb - 1);
    const diferencia = ma - mb;
    const ee = Math.sqrt(va / na + vb / nb);
